pragma solidity ^0.8.20;

// Deployed at: 0x3E506CDa6Bb473A58a11fED3C1e592E4eE33CcB6

/// @notice Owner-only multicall, aggregate3-like.
/// @dev Intended to be called via eth_call (staticCall in ethers) for simulations.
contract OwnerMulticall {
    error NOT_OWNER(address caller);
    error CALL_FAILED(uint256 index, address target);
    error TOO_MANY_CALLS(uint256 calls, uint256 maxCalls);

    address public immutable owner;
    uint256 public immutable maxCalls; // 0 => unlimited

    constructor(address _owner, uint256 _maxCalls) {
        owner = _owner;
        maxCalls = _maxCalls;
    }

    modifier onlyOwner() {
        if (msg.sender != owner) revert NOT_OWNER(msg.sender);
        _;
    }

    struct Call3 {
        address target;
        bool allowFailure;
        bytes callData;
    }

    struct Result {
        bool success;
        bytes returnData;
    }

    /// @notice aggregate3 аналог. Делает обычный call к target'ам.
    /// @dev Если allowFailure=false и call упал — ревертит весь aggregate3.
    function aggregate3(Call3[] calldata calls)
    external
    onlyOwner
    returns (Result[] memory results)
    {
        uint256 n = calls.length;
        uint256 limit = maxCalls;
        if (limit != 0 && n > limit) revert TOO_MANY_CALLS(n, limit);

        results = new Result[](n);

        for (uint256 i = 0; i < n; i++) {
            Call3 calldata c = calls[i];

            // обычный call (НЕ staticcall), чтобы можно было симулировать swap-цепочки в eth_call
            (bool ok, bytes memory ret) = c.target.call(c.callData);

            if (!ok && !c.allowFailure) revert CALL_FAILED(i, c.target);

            results[i] = Result({ success: ok, returnData: ret });
        }
    }
}
